package zw.ac.msu.dzimbahub.controller;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import zw.ac.msu.dzimbahub.auth.*; import zw.ac.msu.dzimbahub.model.*; import zw.ac.msu.dzimbahub.repository.*; import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminController { public record UserSummary(Long id,String fullName,String email,String role,String status,java.time.Instant createdAt){} private UserSummary summary(AppUser u){return new UserSummary(u.getId(),u.getFullName(),u.getEmail(),u.getRole().name(),u.getStatus().name(),u.getCreatedAt());} private final AppUserRepository users; private final PropertyRepository properties; private final UserActionRepository actions; public AdminController(AppUserRepository u,PropertyRepository p,UserActionRepository a){users=u;properties=p;actions=a;}
 @GetMapping("/users/pending") public List<UserSummary> pending(){return users.findByStatusOrderByCreatedAtAsc(AccountStatus.PENDING).stream().map(this::summary).toList();}
 @PutMapping("/users/{id}/approve") public Map<String,Object> approve(@PathVariable Long id){AppUser u=users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(u.getRole()==UserRole.ADMIN)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);u.setStatus(AccountStatus.APPROVED);users.save(u);return Map.of("message","Account approved.","id",id,"status",u.getStatus().name());}
 @PutMapping("/users/{id}/reject") public Map<String,Object> reject(@PathVariable Long id){AppUser u=users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(u.getRole()==UserRole.ADMIN)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);u.setStatus(AccountStatus.REJECTED);users.save(u);return Map.of("message","Account rejected.","id",id,"status",u.getStatus().name());}
 @GetMapping("/users") public List<UserSummary> users(){return users.findAll().stream().map(this::summary).toList();}
 @GetMapping("/stats") public Map<String,Long> stats(){return Map.of("properties",properties.count(),"users",users.count(),"pendingUsers",users.countByStatus(AccountStatus.PENDING),"viewings",actions.countByType("VIEWING"),"messages",actions.countByType("MESSAGE"),"reviews",actions.countByType("REVIEW"));}
 @GetMapping("/actions") public List<UserAction> allActions(){return actions.findAll();}
 @DeleteMapping("/properties/{id}") public Map<String,Object> removeProperty(@PathVariable Long id){if(!properties.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND);properties.deleteById(id);return Map.of("message","Listing removed.");}
}
